CREATE TABLE [KpiEvaluationRecords] (
    [Id] uniqueidentifier NOT NULL,
    [EmployeeKpiTargetId] uniqueidentifier NOT NULL,
    [EvaluatorId] uniqueidentifier NOT NULL,
    [IsSelfEvaluation] bit NOT NULL,
    [IsFinal] bit NOT NULL,
    [ActualValue] decimal(18,4) NULL,
    [AchievementPercent] decimal(18,4) NOT NULL,
    [EvaluationDate] datetime2 NOT NULL,
    [Notes] nvarchar(2000) NULL,
    [EvidenceLinks] nvarchar(4000) NULL,
    [CreatedAt] datetime2 NOT NULL,
    [UpdatedAt] datetime2 NULL,
    [CreatedBy] nvarchar(max) NULL,
    [UpdatedBy] nvarchar(max) NULL,
    [CreatedById] uniqueidentifier NULL,
    [LastModifiedById] uniqueidentifier NULL,
    [IsDeleted] bit NOT NULL,
    [DeletedAt] datetime2 NULL,
    [DeletedBy] nvarchar(max) NULL,
    [TenantId] uniqueidentifier NOT NULL,
    CONSTRAINT [PK_KpiEvaluationRecords] PRIMARY KEY ([Id]),
    CONSTRAINT [FK_KpiEvaluationRecords_EmployeeKpiTargets_EmployeeKpiTargetId] FOREIGN KEY ([EmployeeKpiTargetId]) REFERENCES [EmployeeKpiTargets] ([Id]) ON DELETE NO ACTION,
    CONSTRAINT [FK_KpiEvaluationRecords_Employees_EvaluatorId] FOREIGN KEY ([EvaluatorId]) REFERENCES [Employees] ([Id]) ON DELETE NO ACTION,
    CONSTRAINT [FK_KpiEvaluationRecords_Tenants_TenantId] FOREIGN KEY ([TenantId]) REFERENCES [Tenants] ([Id]) ON DELETE NO ACTION
);
