CREATE TABLE [CriterionScores] (
    [Id] uniqueidentifier NOT NULL,
    [EvaluatorEvaluationId] uniqueidentifier NOT NULL,
    [CriteriaId] uniqueidentifier NOT NULL,
    [NumericScore] int NULL,
    [KpiEvaluationRecordId] uniqueidentifier NULL,
    [WeightedScore] decimal(18,4) NOT NULL,
    [Notes] nvarchar(2000) NULL,
    [CreatedAt] datetime2 NOT NULL,
    [UpdatedAt] datetime2 NULL,
    [CreatedBy] nvarchar(max) NULL,
    [UpdatedBy] nvarchar(max) NULL,
    [CreatedById] uniqueidentifier NULL,
    [LastModifiedById] uniqueidentifier NULL,
    [IsDeleted] bit NOT NULL,
    [DeletedAt] datetime2 NULL,
    [DeletedBy] nvarchar(max) NULL,
    [TenantId] uniqueidentifier NOT NULL,
    CONSTRAINT [PK_CriterionScores] PRIMARY KEY ([Id]),
    CONSTRAINT [FK_CriterionScores_AppraisalCriterias_CriteriaId] FOREIGN KEY ([CriteriaId]) REFERENCES [AppraisalCriterias] ([Id]) ON DELETE NO ACTION,
    CONSTRAINT [FK_CriterionScores_EvaluatorEvaluations_EvaluatorEvaluationId] FOREIGN KEY ([EvaluatorEvaluationId]) REFERENCES [EvaluatorEvaluations] ([Id]) ON DELETE NO ACTION,
    CONSTRAINT [FK_CriterionScores_KpiEvaluationRecords_KpiEvaluationRecordId] FOREIGN KEY ([KpiEvaluationRecordId]) REFERENCES [KpiEvaluationRecords] ([Id]) ON DELETE NO ACTION,
    CONSTRAINT [FK_CriterionScores_Tenants_TenantId] FOREIGN KEY ([TenantId]) REFERENCES [Tenants] ([Id]) ON DELETE NO ACTION
);
